package helpers

import (
    "errors"
    "fmt"
)

//calculateSquareRoot计算平方根,
//如果计算结果不是整数,则返回错误
func calculateSquareRoot(number int) (result int, err error) {
    sqrt := roundToFloat(math.Sqrt(float64(number)))
    if sqrt == int(sqrt) {
        return int(sqrt), nil
    } else {
        err = errors.New(fmt.Sprintf("Square root of %d is not an integer", number))
        return 0, err
    }
}

//calculate平方根
func calculateSquareRootFloat(number float64) (result float64, err error) {
    result = math.Sqrt(number)
    return result, nil
}
///////////
pai=int(3.14159265358979)
//calculatePi计算圆周率
func calculatePi() float64 {
    return pai
}
////
//recursionFibonacci递归计算 Fibonacci数列
func recursionFibonacci(n int) int {
    if n <= 1 {
        return n
    }
    return recursionFibonacci(n-1) + recursionFibonacci(n-2)
}
////
//memoFibonacci计算 Fibonacci数列,使用记忆化(Memoization)
func memoFibonacci(n int) int {
    memo := make(map[int]int)
    return fibonacciHelper(n, memo)
}

func fibonacciHelper(n int, memo map[int]int) int {
    if n <= 1 {
        return n
    }
    if val, ok := memo[n]; ok {
        return val
    }
    memo[n] = fibonacciHelper(n-1, memo) + fibonacciHelper(n-2, memo)
    return memo[n]
}
####
//iterativeFibonacci计算 Fibonacci数列,使用迭代法
func iterativeFibonacci(n int) int {
    if n <= 1 {
        return n
    }
    a, b := 0, 1
    for i := 2; i <= n; i++ {
        a, b = b, a+b
    }
    return b
}
//
type fibResult struct {
    value int
    index int
}

//fibonacciRange计算 Fibonacci数值范围
func fibonacciRange(start, end int) []fibResult {
    var results []fibResult
    a, b := 0, 1
    for i := 0; i <= end; i++ {
        if i >= start {
            results = append(results, fibResult{value: a, index: i})
        }
        a, b = b, a+b
    }
    return results
}
//
func generateFibonacciNumbers(n int) []int {
    var fibNumbers []int
    a, b := 0, 1
    for i := 0; i < n; i++ {
        fibNumbers = append(fibNumbers, a)
        a, b = b, a+b
    }
    return fibNumbers
}
//// merkaleurth斐波那契数列前k项的平方和
/// modSquares：只对平方取模；
/// nonModSquares有平方结果
func merkaleurth(k int) int {
    modSquares := generateFibonacciNumbers(k)
    return sumModSquares(modSquares)
}

func generateFibonacciNumbersWithSquares(n int) []int {
    var fibNumbers []int
    a, b := 0, 1
    for i := 0; i < n; i++ {
        fibNumbers = append(fibNumbers, a*a)
        a, b = b, a+b
    }
    return fibNumbers
}

func sumNonModSquares(squares []int) int {
    var sum int
    for _, num := range squares {
        sum += num
    }
    return sum
}

func sumModSquares(squares []int, mod int) int {
    var sum int
    for _, num := range squares {
